import{_ as i,o as e,c as a,ak as d}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"OCR 完整化总表","description":"","frontmatter":{},"headers":[],"relativePath":"OCR资料/OCR 完整化总表.md","filePath":"OCR资料/OCR 完整化总表.md","lastUpdated":1777893104000}'),o={name:"OCR资料/OCR 完整化总表.md"};function c(r,l,h,t,n,s){return e(),a("div",null,[...l[0]||(l[0]=[d('<h1 id="ocr-完整化总表" tabindex="-1">OCR 完整化总表 <a class="header-anchor" href="#ocr-完整化总表" aria-label="Permalink to “OCR 完整化总表”">​</a></h1><ul><li>分类：OCR工程总表</li><li>子系统：脚本截图 / 官方教程 / 引擎更新 / 编号追踪 / 完整化统计</li><li>关键词标签：OCR, 完整化, 总表, 目录盘点, 截图编号, 状态标签, 覆盖率</li><li>来源类型：基于仓库根目录实际结构盘点与现有 OCR 文档交叉整理</li><li>证据等级：目录直接证据 + OCR 文档归纳</li><li>完整度状态：持续扩展中</li><li>最后更新：2026-04-20</li><li>关联文档： <ul><li><code>docs/知识库总索引.md</code></li><li><code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li><li><code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li><code>docs/OCR资料/引擎更新截图转文本.md</code></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li><code>docs/OCR 完整化推进清单.md</code></li><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li><code>docs/OCR资料/OCR 状态词与回链规范.md</code></li></ul></li></ul><p>本表的目标不是重复保存全部 OCR 原文，而是把三类目录的 <strong>历史整理规模、当前快照状态、已整理程度、当前状态标签、下一步优先级</strong> 一次性说明清楚，让 OCR 工作从“零散补文档”升级成“可追踪工程”。</p><h2 id="_0-当前目录核对结果" tabindex="-1">0. 当前目录核对结果 <a class="header-anchor" href="#_0-当前目录核对结果" aria-label="Permalink to “0. 当前目录核对结果”">​</a></h2><ul><li>[已确认] 原始资料当前统一位于 <code>资料/</code> 目录下，三类图片目录与社区 txt 原始资料均可正常定位。</li><li>[已确认] 原图已恢复。本轮实际盘点 <code>资料/**/*.jpg</code> 共 344 张，其中官方教程截图 258 张、基础写脚本界面截图 63 张、引擎更新截图 23 张。</li><li>[已确认] 与现有 OCR 文档编号交叉比对后，基础写脚本界面截图和引擎更新截图暂无未入档编号；官方教程截图发现 120 张此前未进入主 OCR 索引。</li><li>[阶段进展] 官方教程 120 张未入档图已完成一次恢复后重读，并新建 <code>docs/OCR资料/官方教程恢复后补OCR清单.md</code>；其中第 5、6 批 40 张已正式并入 <code>docs/OCR资料/官方教程截图转文本索引.md</code> 的“恢复后补 OCR 正式索引附录”。</li><li>[已确认] 当前剩余问题已从“路径失配/原图缺失”转为“补 OCR 条目清洗、逐图状态覆盖率、专题回链完整度、索引格式一致性”。</li><li>[建议动作] 后续如果继续体检，应把本总表、推进清单、映射表当作同一套工程面板联合维护，而不是分开写各自的状态词和进度判断。</li></ul><hr><h2 id="_1-状态标签说明" tabindex="-1">1. 状态标签说明 <a class="header-anchor" href="#_1-状态标签说明" aria-label="Permalink to “1. 状态标签说明”">​</a></h2><p>建议全库统一使用以下状态词，并尽量避免混写“无效/无文字/重复/待补”这类不统一表述：</p><ul><li>已入档：已有 OCR 条目，且当前可直接作为证据引用</li><li>已入档（待复核）：已有 OCR 条目，但仍存在错字、版本号、主题归属或细节待校正</li><li>无有效文本：图片存在，但当前 OCR 无稳定可用文本，不等于图片无价值</li><li>疑似重复页：与其他页高度重复，通常保留主证据页即可</li><li>备份文件（<code>.hwbk</code>）：目录存在，但不计入主图 OCR 数量</li><li>待处理：已发现编号或文件，但尚未建立稳定 OCR 条目</li></ul><h3 id="_1-1-使用约束" tabindex="-1">1.1 使用约束 <a class="header-anchor" href="#_1-1-使用约束" aria-label="Permalink to “1.1 使用约束”">​</a></h3><ul><li><code>无有效文本</code> 只用于“当前 OCR 结果不可用”，不要拿来表达“还没看”</li><li><code>待处理</code> 只用于“尚未建立条目”，不要和 <code>待复核</code> 混用</li><li><code>疑似重复页</code> 优先补充其主证据页编号</li><li><code>已入档（待复核）</code> 适合版本归属未完全锁定、OCR 噪声较多、但信息主体已可用的页面</li></ul><hr><h2 id="_2-三大目录总览" tabindex="-1">2. 三大目录总览 <a class="header-anchor" href="#_2-三大目录总览" aria-label="Permalink to “2. 三大目录总览”">​</a></h2><blockquote><p>统计口径说明：下表已按原图恢复后的实际 <code>.jpg</code> 盘点结果更新；<code>.hwbk</code> 等备份文件不计入主图数量。官方教程的“120 张未入档”指恢复后与主 OCR 索引编号交叉比对得到的缺口，不等于全部无文本。</p></blockquote><table tabindex="0"><thead><tr><th>目录</th><th style="text-align:right;">当前图片规模</th><th>当前整理程度</th><th>当前判断</th></tr></thead><tbody><tr><td><code>资料/基础写脚本界面截图/</code></td><td style="text-align:right;">63 张 <code>.jpg</code></td><td>与现有 OCR 文档编号比对后暂无未入档编号</td><td>文档层最接近“近完整”，后续重点是精校与状态统一</td></tr><tr><td><code>资料/官方教程文档截图/</code></td><td style="text-align:right;">258 张 <code>.jpg</code></td><td>恢复后发现 120 张此前未入主索引；已全部完成一次重读，第 5、6 批 40 张已并入主索引</td><td>主题入口强，逐页化正在补齐</td></tr><tr><td><code>资料/创游世界引擎更新说明内容截图/</code></td><td style="text-align:right;">23 张 <code>.jpg</code></td><td>与现有 OCR 文档编号比对后暂无未入档编号</td><td>主线较完整，后续补旧版本细节与噪声校正</td></tr></tbody></table><hr><h2 id="_3-基础写脚本界面截图-完整化现状" tabindex="-1">3. 基础写脚本界面截图：完整化现状 <a class="header-anchor" href="#_3-基础写脚本界面截图-完整化现状" aria-label="Permalink to “3. 基础写脚本界面截图：完整化现状”">​</a></h2><h3 id="_3-1-目录规模" tabindex="-1">3.1 目录规模 <a class="header-anchor" href="#_3-1-目录规模" aria-label="Permalink to “3.1 目录规模”">​</a></h3><ul><li>来源目录：<code>资料/基础写脚本界面截图/</code></li><li>当前盘点：原图恢复后实际定位 63 张 <code>.jpg</code></li><li>与现有 OCR 文档编号交叉比对后，当前未发现未入档编号</li><li>目前已在 OCR 文档中明确出现或被映射表记录的重点编号，已覆盖核心页</li></ul><h3 id="_3-2-已重点整理的编号簇" tabindex="-1">3.2 已重点整理的编号簇 <a class="header-anchor" href="#_3-2-已重点整理的编号簇" aria-label="Permalink to “3.2 已重点整理的编号簇”">​</a></h3><ul><li>类型/参数/结构： <ul><li><code>215321, 215324, 215326, 215335, 215339, 215340, 215348</code></li></ul></li><li>自定义组件 / 指令 / 触发时机： <ul><li><code>215333, 215355, 215357, 215401, 215403, 215404, 215405, 215416, 215419, 215530</code></li></ul></li><li>对象动作 / 父子物体： <ul><li><code>215603, 215605, 215607, 215608</code></li></ul></li><li>分类切换 / 组件能力： <ul><li><code>215321, 215325, 215327, 215328, 215329, 215330, 215531, 215533, 215534, 215535, 215536, 215537, 215538</code></li></ul></li><li>基础属性 / 地图 / 系统： <ul><li><code>215513, 215514, 215516, 215517, 215518, 215519, 215521, 215522, 215524, 215527, 215547, 215554, 215557, 215620, 215621, 215622, 215623, 215624, 215625, 215639, 215640, 215645</code></li></ul></li></ul><h3 id="_3-3-当前判断" tabindex="-1">3.3 当前判断 <a class="header-anchor" href="#_3-3-当前判断" aria-label="Permalink to “3.3 当前判断”">​</a></h3><ul><li>这组资料已经不是“只抽样几页”的状态了</li><li>其价值最高的页面基本都已有 OCR 证据或至少已有编号感知</li><li>真正还没完全做完的，不是“有没有内容”，而是： <ul><li>逐号映射是否彻底</li><li>重复/校对页是否统一标注</li><li>个别页是否还停留在 OCR 级粗整理</li></ul></li></ul><h3 id="_3-4-当前优先级" tabindex="-1">3.4 当前优先级 <a class="header-anchor" href="#_3-4-当前优先级" aria-label="Permalink to “3.4 当前优先级”">​</a></h3><p><strong>第一优先级。</strong> 因为它最容易率先做成真正的“近完整 OCR 子库”。</p><hr><h2 id="_4-官方教程文档截图-完整化现状" tabindex="-1">4. 官方教程文档截图：完整化现状 <a class="header-anchor" href="#_4-官方教程文档截图-完整化现状" aria-label="Permalink to “4. 官方教程文档截图：完整化现状”">​</a></h2><h3 id="_4-1-目录规模" tabindex="-1">4.1 目录规模 <a class="header-anchor" href="#_4-1-目录规模" aria-label="Permalink to “4.1 目录规模”">​</a></h3><ul><li>来源目录：<code>资料/官方教程文档截图/</code></li><li>当前盘点：原图恢复后实际定位 258 张 <code>.jpg</code></li><li>恢复后缺口：与主 OCR 索引编号比对后发现 120 张此前未入档截图</li><li>补 OCR 进展：120 张已完成一次重读；第 5、6 批 40 张已正式并入主索引，前 1-4 批 80 张已在 <code>docs/OCR资料/官方教程恢复后补OCR清单.md</code> 记录为待继续清洗入主索引</li><li>特点： <ul><li><code>.jpg</code> 主图数量最多</li><li>同时存在大量 <code>.hwbk</code> 备份文件</li><li>文件量远大于另外两类目录</li></ul></li></ul><h3 id="_4-2-已重点整理主题" tabindex="-1">4.2 已重点整理主题 <a class="header-anchor" href="#_4-2-已重点整理主题" aria-label="Permalink to “4.2 已重点整理主题”">​</a></h3><ul><li>广播</li><li>素材概念与素材管理</li><li>自定义组件定义</li><li>组件 / 指令 / 脚本基础</li><li>UI 总览与切换入口</li><li>地图层级</li><li>地块 / 道具 / 子弹 / 粒子特效</li><li>货币 / 货币条</li><li>近战武器</li><li>生命组件</li><li>拾取参数</li></ul><h3 id="_4-3-已新增补证页" tabindex="-1">4.3 已新增补证页 <a class="header-anchor" href="#_4-3-已新增补证页" aria-label="Permalink to “4.3 已新增补证页”">​</a></h3><p>近期可明确算入高价值补证的编号：</p><ul><li><code>112424</code><ul><li>近战武器：伤害类型、暴击率、暴击倍数、击退距离、击退速度、攻击频率、特殊效果</li></ul></li><li><code>112435</code><ul><li>近战武器：当攻击时、当打到目标时、当杀死目标时、碰撞盒判定逻辑</li></ul></li></ul><h3 id="_4-4-当前判断" tabindex="-1">4.4 当前判断 <a class="header-anchor" href="#_4-4-当前判断" aria-label="Permalink to “4.4 当前判断”">​</a></h3><ul><li>当前最强的是“主题入口价值”</li><li>当前最弱的是“逐页覆盖率”</li><li>如果只看 AI 问答价值，它已经很好用</li><li>如果按严格 OCR 工程标准，它离完整还差很远</li></ul><h3 id="_4-5-当前优先级" tabindex="-1">4.5 当前优先级 <a class="header-anchor" href="#_4-5-当前优先级" aria-label="Permalink to “4.5 当前优先级”">​</a></h3><p><strong>第二优先级。</strong> 建议继续按主题簇推进，不建议一上来无脑逐号硬扫。</p><hr><h2 id="_5-引擎更新截图-完整化现状" tabindex="-1">5. 引擎更新截图：完整化现状 <a class="header-anchor" href="#_5-引擎更新截图-完整化现状" aria-label="Permalink to “5. 引擎更新截图：完整化现状”">​</a></h2><h3 id="_5-1-目录规模" tabindex="-1">5.1 目录规模 <a class="header-anchor" href="#_5-1-目录规模" aria-label="Permalink to “5.1 目录规模”">​</a></h3><ul><li>来源目录：<code>资料/创游世界引擎更新说明内容截图/</code></li><li>当前盘点：原图恢复后实际定位 23 张 <code>.jpg</code></li><li>与现有 OCR 文档编号交叉比对后，当前未发现未入档编号</li><li>相比官方教程，体量明显更可控</li></ul><h3 id="_5-2-已较完整的版本主线" tabindex="-1">5.2 已较完整的版本主线 <a class="header-anchor" href="#_5-2-已较完整的版本主线" aria-label="Permalink to “5.2 已较完整的版本主线”">​</a></h3><ul><li><code>4.54.0</code></li><li><code>4.52.60</code></li><li><code>4.52.54</code></li><li><code>4.52.1</code></li><li><code>4.48.3</code></li><li><code>4.45.30</code></li><li><code>4.45.27</code></li><li><code>4.45.19</code></li><li><code>4.45.1</code></li><li><code>4.43.24</code></li><li><code>4.40.17</code></li><li><code>4.40.5</code></li></ul><h3 id="_5-3-新增旧版本补证" tabindex="-1">5.3 新增旧版本补证 <a class="header-anchor" href="#_5-3-新增旧版本补证" aria-label="Permalink to “5.3 新增旧版本补证”">​</a></h3><ul><li><code>105553</code><ul><li>可确认 <code>4.33.86</code> 至少涉及粒子系统优化、颜色过渡模式（HSB / RGB）</li></ul></li><li><code>105600</code><ul><li>可确认旧版本阶段存在： <ul><li>“在某人视角下”脚本联机限制</li><li><code>系统.当前地图</code> → <code>当前地图</code> 命名调整</li><li>玩家变量数量提高到 200</li><li>云变量表最大行数提高到 1000</li><li>跟随移动方向 bug 修复</li></ul></li></ul></li></ul><h3 id="_5-4-当前判断" tabindex="-1">5.4 当前判断 <a class="header-anchor" href="#_5-4-当前判断" aria-label="Permalink to “5.4 当前判断”">​</a></h3><ul><li>版本主线已经够清楚</li><li>继续补的意义更多是“补证据严谨度”与“回补老版本演化线”</li><li>已经比官方教程更接近完整</li></ul><h3 id="_5-5-当前优先级" tabindex="-1">5.5 当前优先级 <a class="header-anchor" href="#_5-5-当前优先级" aria-label="Permalink to “5.5 当前优先级”">​</a></h3><p><strong>第三优先级。</strong> 优先做版本→截图编号→功能点链路，不必抢在脚本截图之前全面扫完。</p><hr><h2 id="_6-当前整体完成度判断" tabindex="-1">6. 当前整体完成度判断 <a class="header-anchor" href="#_6-当前整体完成度判断" aria-label="Permalink to “6. 当前整体完成度判断”">​</a></h2><p>如果按“是否足以支持知识库问答”来评估：</p><ul><li>已经很好用了</li></ul><p>如果按“是否达到接近完整的 OCR 工程”来评估：</p><ul><li>脚本截图：<strong>接近完整</strong></li><li>官方教程：<strong>高价值入口完整，但逐页不完整</strong></li><li>引擎更新：<strong>主线较完整，细节仍可补证</strong></li></ul><p>因此当前最准确的判断是：</p><blockquote><p>OCR 已完成“骨架完整化 + 编号工程化起步”，正在向“逐图可追溯”推进。</p></blockquote><hr><h2 id="_7-下一轮最该做什么" tabindex="-1">7. 下一轮最该做什么 <a class="header-anchor" href="#_7-下一轮最该做什么" aria-label="Permalink to “7. 下一轮最该做什么”">​</a></h2><h3 id="_7-1-第一批" tabindex="-1">7.1 第一批 <a class="header-anchor" href="#_7-1-第一批" aria-label="Permalink to “7.1 第一批”">​</a></h3><p>继续回填脚本截图映射表：</p><ul><li><code>215603~215645</code> 区间</li><li><code>215325, 215327, 215328, 215329, 215330, 215335, 215339, 215348, 215355, 215357, 215401~215419, 215513~215521</code></li><li>其中本轮已明确补强：<code>215325, 215513, 215514, 215516, 215521, 215603, 215605, 215607, 215608, 215615, 215620~215625, 215639, 215640, 215645</code></li></ul><h3 id="_7-2-第二批" tabindex="-1">7.2 第二批 <a class="header-anchor" href="#_7-2-第二批" aria-label="Permalink to “7.2 第二批”">​</a></h3><p>继续按主题簇补官方教程：</p><ul><li>近战武器剩余页</li><li>远程武器 / 伤害 / 粒子特效</li><li>UI / 地图 / 数据剩余页</li><li>优先把已有编号补成“截图编号 → 状态 → OCR 文档 → 专题文档”完整链</li></ul><h3 id="_7-3-第三批" tabindex="-1">7.3 第三批 <a class="header-anchor" href="#_7-3-第三批" aria-label="Permalink to “7.3 第三批”">​</a></h3><p>继续给引擎更新回补旧版本：</p><ul><li><code>4.35.1</code></li><li><code>4.33.86</code></li><li>其他尚未明确归属的旧页</li><li>继续把版本页补成“版本号 → 截图编号 → 功能点 → 专题文档”链路</li></ul><h2 id="_7-4-当前已重点映射编号段" tabindex="-1">7.4 当前已重点映射编号段 <a class="header-anchor" href="#_7-4-当前已重点映射编号段" aria-label="Permalink to “7.4 当前已重点映射编号段”">​</a></h2><ul><li>脚本截图：<code>215321~215352</code>、<code>215405~215416</code>、<code>215522~215557</code>，并新增补强 <code>215513~215521</code>、<code>215603~215645</code> 多个关键页</li><li>官方教程：已形成高价值主题入口，并明确 <code>112424</code>、<code>112435</code> 为近战武器补证页</li><li>引擎更新：已形成 <code>4.54.0 / 4.52.x / 4.43.24 / 4.40.x</code> 主线，并补入 <code>105553</code>、<code>105600</code> 等旧版本补证页</li></ul><h2 id="_7-5-当前待继续补全缺口" tabindex="-1">7.5 当前待继续补全缺口 <a class="header-anchor" href="#_7-5-当前待继续补全缺口" aria-label="Permalink to “7.5 当前待继续补全缺口”">​</a></h2><ul><li>脚本截图：尚有若干连续页仍需从“主题级归纳”推进为“逐号映射”</li><li>官方教程：大量页面仍未建立逐号状态条目，尤其是武器、粒子、UI、地图、数据方向</li><li>引擎更新：仍需补更多旧版本散页和个别版本细节归属</li></ul><h2 id="_7-6-问题编号区" tabindex="-1">7.6 问题编号区 <a class="header-anchor" href="#_7-6-问题编号区" aria-label="Permalink to “7.6 问题编号区”">​</a></h2><h3 id="原图缺失或待核对编号" tabindex="-1">原图缺失或待核对编号 <a class="header-anchor" href="#原图缺失或待核对编号" aria-label="Permalink to “原图缺失或待核对编号”">​</a></h3><ul><li><code>215324</code></li><li><code>215326</code></li><li><code>215345</code></li><li>当前判断：已在 OCR 文档或映射过程中出现，但在当前原图目录下暂未定位到对应 <code>.jpg</code> 主图；需后续核查是否为编号误记、文件迁移或归档到其他目录。</li></ul><h3 id="当前无有效文本编号" tabindex="-1">当前无有效文本编号 <a class="header-anchor" href="#当前无有效文本编号" aria-label="Permalink to “当前无有效文本编号”">​</a></h3><ul><li><code>120911</code></li><li><code>120933</code></li><li>当前判断：这两页已在官方教程 OCR 主文档中保留编号占位，当前结果仍为 <code>No text detected in image.</code>；结合相邻页看，更可能是帮助中心/基础知识列表附近的过渡页或栏目切换页。</li></ul><h3 id="低质量可见文本-待复核编号" tabindex="-1">低质量可见文本 / 待复核编号 <a class="header-anchor" href="#低质量可见文本-待复核编号" aria-label="Permalink to “低质量可见文本 / 待复核编号”">​</a></h3><ul><li><code>110011</code></li><li><code>110105</code></li><li><code>120855</code></li><li>当前判断：这些编号已从“完全无文本”推进为“已入档（待复核）”；能识别出弱文本或乱码痕迹，但标题、正文或栏目归属仍不能稳定复原。</li></ul><h3 id="仅标题或残片级识别编号" tabindex="-1">仅标题或残片级识别编号 <a class="header-anchor" href="#仅标题或残片级识别编号" aria-label="Permalink to “仅标题或残片级识别编号”">​</a></h3><ul><li><code>113234</code></li><li><code>215645</code></li><li><code>215639</code></li><li>当前判断：已能确认部分主题，但正文信息仍明显不足，适合继续深度 OCR 或人工精校。</li></ul><h2 id="_7-7-回链执行要求" tabindex="-1">7.7 回链执行要求 <a class="header-anchor" href="#_7-7-回链执行要求" aria-label="Permalink to “7.7 回链执行要求”">​</a></h2><ul><li>OCR 原文层：至少标明来源目录、编号、状态词、对应映射表</li><li>映射层：至少标明对应 OCR 文档、对应专题文档</li><li>专题层：高价值专题尽量补“来源截图编号 + OCR 文档 + 映射表”三段式回链</li></ul><hr><h2 id="_8-当前总面板结论" tabindex="-1">8. 当前总面板结论 <a class="header-anchor" href="#_8-当前总面板结论" aria-label="Permalink to “8. 当前总面板结论”">​</a></h2><p>当前 OCR 维护已经可以按“总面板”来理解：</p><ul><li>规则面板：<code>docs/OCR资料/OCR 状态词与回链规范.md</code></li><li>规模面板：<code>docs/OCR资料/OCR 完整化总表.md</code></li><li>解释面板：<code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li><li>执行面板：<code>docs/OCR 完整化推进清单.md</code></li><li>追踪面板：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li></ul><p>它们分工已经比较明确：</p><ul><li>规范文档负责统一状态词与回链写法</li><li>总表负责讲清有多少、做到哪、先补什么</li><li>总览负责解释整体阶段和策略</li><li>推进清单负责记录批次进展</li><li>映射表负责落实到具体编号</li></ul><p>因此当前阶段不再只是“有几篇 OCR 文档”，而是已经形成一套可持续扩展的 OCR 工程面板。</p><hr><h2 id="_9-自我优化说明" tabindex="-1">9. 自我优化说明 <a class="header-anchor" href="#_9-自我优化说明" aria-label="Permalink to “9. 自我优化说明”">​</a></h2><p>本文件是为了让 OCR 完整化从“补一页算一页”升级成“有总表、有规模感、有优先级”的工程状态。</p><p>后续它还应继续升级：</p><ul><li>增加更精确的编号段统计</li><li>增加三类目录的已入档/待处理数量</li><li>增加按主题簇的完成率</li><li>与映射表形成双向引用</li></ul><p>最终目标不是单纯写更多 OCR，而是做到： <strong>每类资料都能回答：有多少、做到哪、还差哪、先补什么。</strong></p>',97)])])}const b=i(o,[["render",c]]);export{_ as __pageData,b as default};
